‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍
 */

class SchemaSync
{
    private static ?array $cache = null;

    private static function schemaPath(): string
    {
        return __DIR__ . '/../schema.sql';
    }

    /**
     * Parse schema.sql into:
     *   [ table => [ column => ['def' => string, 'after' => ?string], ... ] ]
     * preserving column order. Constraint / key lines are skipped.
     *
     * @return array<string, array<string, array{def:string, after:?string}>>
     */
    public static function expectedColumns(): array
    {
        if (self::$cache !== null) {
            return self::$cache;
        }
        $sql = @file_get_contents(self::schemaPath());
        if ($sql === false) {
            return self::$cache = [];
        }
        // Drop full-line comments so a ';' or ',' inside a comment can't confuse parsing.
        $sql = preg_replace('/^\s*--.*$/m', '', $sql);

        $tables = [];
        if (preg_match_all('/CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?`?(\w+)`?\s*\(/i', $sql, $m, PREG_OFFSET_CAPTURE)) {
            foreach ($m[1] as $i => $nameCap) {
                $table = $nameCap[0];
                // index of the '(' that opens this table body
                $openParen = $m[0][$i][1] + strlen($m[0][$i][0]) - 1;
                $body = self::extractBalanced($sql, $openParen);
                if ($body === null) {
                    continue;
                }
                $cols = self::parseColumns($body);
                if ($cols) {
                    $tables[$table] = $cols;
                }
            }
        }
        return self::$cache = $tables;
    }

    /** Given the index of '(' in $s, return the substring inside the matching ')'. */
    private static function extractBalanced(string $s, int $openIdx): ?string
    {
        $depth = 0;
        $len = strlen($s);
        for ($i = $openIdx; $i < $len; $i++) {
            $ch = $s[$i];
            if ($ch === '(') {
                $depth++;
            } elseif ($ch === ')') {
                $depth--;
                if ($depth === 0) {
                    return substr($s, $openIdx + 1, $i - $openIdx - 1);
                }
            }
        }
        return null;
    }

    /** Split a CREATE TABLE body at top-level commas and pick out column definitions. */
    private static function parseColumns(string $body): array
    {
        // Split on commas that are NOT inside parentheses (e.g. DECIMAL(32,16),
        // ENUM('login','logout') must stay intact). Also handle single/double quotes so
        // commas inside DEFAULT values (e.g. DEFAULT ',') do not split definitions.
        $parts = [];
        $depth = 0;
        $inQuote = false;
        $quoteChar = '';
        $escaped = false;
        $buf = '';
        $len = strlen($body);
        for ($i = 0; $i < $len; $i++) {
            $ch = $body[$i];
            if ($inQuote) {
                $buf .= $ch;
                if ($escaped) {
                    $escaped = false;
                } elseif ($ch === '\\') {
                    $escaped = true;
                } elseif ($ch === $quoteChar) {
                    $inQuote = false;
                }
                continue;
            }

            if ($ch === "'" || $ch === '"' || $ch === '`') {
                $inQuote = true;
                $quoteChar = $ch;
                $buf .= $ch;
                continue;
            }

            if ($ch === '(') {
                $depth++;
            } elseif ($ch === ')') {
                $depth--;
            }
            if ($ch === ',' && $depth === 0) {
                $parts[] = $buf;
                $buf = '';
            } else {
                $buf .= $ch;
            }
        }
        if (trim($buf) !== '') {
            $parts[] = $buf;
        }

        $skip = ['PRIMARY', 'FOREIGN', 'UNIQUE', 'KEY', 'INDEX', 'CONSTRAINT', 'CHECK', 'FULLTEXT', 'SPATIAL'];
        $cols = [];

