​‌‌‌​‌​‌​‌‌​‌‌‌​​‌‌​​​​‌​‌‌‌​‌​‌​‌‌‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍ */
        $prev = null;
        foreach ($parts as $part) {
            $part = trim(preg_replace('/\s+/', ' ', $part));
            if ($part === '') {
                continue;
            }
            // First token is either the column name or a constraint keyword.
            $first = strtoupper(preg_replace('/[^A-Za-z].*$/', '', ltrim($part, '`')));
            if (in_array($first, $skip, true)) {
                continue;
            }
            if (!preg_match('/^`?([A-Za-z_][A-Za-z0-9_]*)`?\s+(.*)$/', $part, $cm)) {
                continue;
            }
            $cols[$cm[1]] = ['def' => trim($cm[2]), 'after' => $prev];
            $prev = $cm[1];
        }
        return $cols;
    }

    /**
     * Add any missing columns to EXISTING tables so they match schema.sql.
     * Missing tables are NOT handled here (applySchema creates those).
     *
     * @return array{added: string[], failed: string[]} e.g. added ['customers.loyalty_points']
     */
    public static function reconcileColumns(PDO $db): array
    {
        $expected = self::expectedColumns();
        $added = [];
        $failed = [];

        $liveTables = $db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) ?: [];
        $liveTablesLower = array_map('strtolower', $liveTables);

        // Fetch all existing columns in a single batch query (avoids 58+ N+1 roundtrips)
        $liveColsByTable = [];
        try {
            $colStmt = $db->query('SELECT LOWER(TABLE_NAME) AS t, LOWER(COLUMN_NAME) AS c FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()');
            while ($row = $colStmt->fetch(PDO::FETCH_NUM)) {
                $liveColsByTable[$row[0]][] = $row[1];
            }
        } catch (\Throwable $e) {
            $liveColsByTable = [];
        }

        foreach ($expected as $table => $cols) {
            $tLower = strtolower($table);
            if (!in_array($tLower, $liveTablesLower, true)) {
                continue; // table itself is missing — applySchema's job
            }
            $liveCols = $liveColsByTable[$tLower] ?? [];
            if (empty($liveCols) && empty($liveColsByTable)) {
                $stmt = $db->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :t');
                $stmt->execute(['t' => $table]);
                $liveCols = array_map('strtolower', $stmt->fetchAll(PDO::FETCH_COLUMN) ?: []);
            }

            foreach ($cols as $col => $meta) {
                if (in_array(strtolower($col), $liveCols, true)) {
                    continue;
                }
                $defUpper = strtoupper($meta['def']);
                if (strpos($defUpper, 'AUTO_INCREMENT') !== false || strpos($defUpper, 'PRIMARY KEY') !== false) {
                    // Never synthesise an identity / primary-key column on a populated table.
                    $failed[] = "{$table}.{$col} (skipped: identity/primary-key column — rebuild this table manually)";
                    continue;
                }
                $tEsc = str_replace('`', '', $table);
                $cEsc = str_replace('`', '', $col);
                $sql = "ALTER TABLE `{$tEsc}` ADD COLUMN `{$cEsc}` {$meta['def']}";
                if (!empty($meta['after']) && in_array(strtolower($meta['after']), $liveCols, true)) {
                    $sql .= " AFTER `" . str_replace('`', '', $meta['after']) . "`";
                }
                try {
                    $db->exec($sql);
                    $added[] = "{$table}.{$col}";
                    $liveCols[] = strtolower($col); // keep AFTER references valid for later columns
                } catch (\Throwable $e) {
                    $failed[] = "{$table}.{$col} (" . $e->getMessage() . ")";
                }
            }
        }

        // Automatic column definition widening/upgrades for existing columns (SEC-01 AES-256-GCM Envelope)
        try {
            $db->exec("ALTER TABLE `settings` MODIFY `recovery_code_plain` VARCHAR(255) NULL");
        } catch (\Throwable $e) {}
        try {
            $db->exec("ALTER TABLE `users` MODIFY `recovery_code_plain` VARCHAR(255) NULL");
        } catch (\Throwable $e) {}
        try {
            $db->exec("ALTER TABLE `conversations` MODIFY `type` ENUM('direct', 'group', 'channel') NOT NULL DEFAULT 'direct'");
        } catch (\Throwable $e) {}
        try {
            $cmCols = array_map('strtolower', $db->query("SHOW COLUMNS FROM `conversation_members`")->fetchAll(\PDO::FETCH_COLUMN) ?: []);
            if (!in_array('can_manage_members', $cmCols, true)) {
                $db->exec("ALTER TABLE `conversation_members` ADD COLUMN `can_manage_members` TINYINT(1) NOT NULL DEFAULT 0 AFTER `can_post`");
            }
        } catch (\Throwable $e) {}
        try {
            $userCols = array_map('strtolower', $db->query("SHOW COLUMNS FROM `users`")->fetchAll(\PDO::FETCH_COLUMN) ?: []);
            if (!in_array('two_factor_secret', $userCols, true)) {
                $db->exec("ALTER TABLE `users` ADD COLUMN `two_factor_secret` TEXT NULL AFTER `recovery_code_last_used_at`");
            }
            if (!in_array('two_factor_enabled', $userCols, true)) {
